import {initial,transition,restore} from './engine.js';
import {englishVoices,chooseVoice,loadVoices} from './speech.js';
let preferredVoice='';try{preferredVoice=localStorage.getItem('campus-voice')||'';}catch{}
let speechRequest=0;
const KEY='campus-quest-v1';let storage=true,s;try{s=restore(localStorage.getItem(KEY));}catch{s=initial();storage=false;}
let view=s.complete?'review':s.prepared?'map':'prep',subtitles=true,hint=0,message='Hey, explorer! I’m Nova. Ready to find Pip together?',translation='我是 Nova，你的同行教练。你来决定路线，我陪你一起寻找 Pip。',notice='',recording=null,chosen=false,quiz=false,transfer=false;
const places={plaza:{name:'科技节广场',en:'Festival Plaza',icon:'🎪',x:17,y:52},library:{name:'图书馆',en:'Library',icon:'🏛️',x:51,y:46},art:{name:'美术教室',en:'Art Room',icon:'🎨',x:82,y:49},greenhouse:{name:'温室',en:'Greenhouse',icon:'🌿',x:51,y:17},gym:{name:'体育馆',en:'Gym',icon:'🏀',x:51,y:80}};
const clues={witness:['目击记录','Pip went past the library, towards the art room.','Pip 经过图书馆，向美术教室走去。'],record:['设备记录','10:20 — blue light flashing.','10:20，蓝灯闪烁。Pip 追逐明亮物品时会闪蓝灯。'],decoration:['装饰物的去向','We carried a shiny decoration to the greenhouse.','美术社把闪亮的装饰物搬到了温室。']};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,cls='secondary',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text}</button>`;
function commit(a,v){s=transition(s,a,v);try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storage=false;}}
function say(en,zh){message=en;translation=zh;render();}
function stopSpeech(){speechRequest++;window.speechSynthesis?.cancel();}
async function speak(text,slow=false){
 if(!('speechSynthesis' in window)){notice='此浏览器不支持语音播放，可以阅读文字继续。';render();return;}
 const request=++speechRequest,synth=window.speechSynthesis;
 synth.cancel();
 const voices=await loadVoices(synth);
 if(request!==speechRequest)return;
 const voice=chooseVoice(voices,preferredVoice);
 if(!voice){notice='没有找到英语音色。请在设备中启用英语语音，或更换浏览器；暂时可用文字继续。';render();return;}
 const u=new SpeechSynthesisUtterance(text);
 u.voice=voice;u.lang=voice.lang;u.rate=slow?.85:1;u.pitch=1;u.volume=1;
 u.onerror=e=>{if(request!==speechRequest||['canceled','interrupted'].includes(e.error))return;notice='当前英语音色播放失败，请换一个音色或浏览器重试。';render();};
 synth.resume();synth.speak(u);
}
function voiceOptions(){const voices=englishVoices(window.speechSynthesis?.getVoices()||[]);return '<option value="">自动选择英语音色</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}" ${preferredVoice===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('');}
function voiceSettings(){return `<div class="voice-settings"><label for="voice-choice">英语音色</label><select id="voice-choice">${voiceOptions()}</select>${btn('试听音色','voice-preview','chip')}<small>使用设备语音，音质因设备而异；可切换音色比较。</small></div>`;}

function goal(){if(!s.started)return'在广场领取寻找 Pip 的任务';if(s.clues.length<3)return`探索校园，收集线索 ${s.clues.length}/3`;if(!s.awake)return'辨认 Pip，并根据说明唤醒它';if(!s.following)return'用英语邀请 Pip 跟你回去';if(!s.complete)return'返回科技节广场，交付任务';return'任务完成！试试新的位置挑战';}
function prep(){return `<section class="card prep"><div class="eyebrow">BEFORE THE ADVENTURE</div><h2 style="margin-top:10px">装好你的语言背包</h2><p class="muted">先认识本关会遇到的词。点卡片听发音，冒险时也能回来查看。</p>${voiceSettings()}<div class="vocabgrid">${[['🤖','robot','机器人'],['🏛️','library','图书馆'],['🌿','greenhouse','温室'],['↩','behind','在……后面'],['✨','flashing','闪烁的'],['🟢','button','按钮']].map(([i,w,z])=>`<button class="word" data-speak="${w}"><em>${i}</em><b>${w} <small>◖))</small></b><span>${z}</span></button>`).join('')}</div><div class="phrases">${['Have you seen a small robot?','Could you say that again?','Let’s check the library.'].map(t=>`<button class="phrase" data-speak="${t}">◖)) &nbsp; ${t}</button>`).join('')}</div><div class="exercise"><b>听一听，它在哪里？</b><p>播放位置描述，再选择对应地点。</p>${btn('◖)) 播放题目','quiz-audio')} ${btn('慢速重听','quiz-slow','chip')}<div class="actions" style="margin-top:12px">${btn('图书馆后面','quiz-right')}${btn('图书馆前面','quiz-wrong')}</div><p id="quiz-result" role="status">${quiz?'✓ 正确！behind 表示在后面。':''}</p></div><div class="actions">${btn('准备好了，出发 →','begin','primary',quiz?'':'disabled')}${btn(s.prepared?'返回探索':'这些已掌握，跳过准备','skip','secondary')}</div></section>`;}
function scene(){let p=places[s.location],body='',actions='';if(!s.prepared){body='先完成语言准备，再领取任务。';actions=btn('去准备','prep');}else if(s.location==='plaza'){body=s.complete?'Pip 已经回到展台。谢谢你，校园探索员！':s.following?'Pip 正跟在你身后。把它带到展台，告诉负责人你完成了任务。':'迎宾机器人 Pip 不见了。它是白色的，带着一盏蓝色指示灯。';actions=s.complete?btn('查看复盘','review','primary'):s.following?btn('把 Pip 带回展台','finish','primary'):!s.started?btn('领取任务 · 寻找 Pip','start','primary'):btn('再听一次外观描述','brief');}else if(!s.started){body='可以先四处看看，记得回到广场领取任务。';actions=btn('前往广场','move','primary','data-value="plaza"');}else if(s.location==='library'){body='管理员似乎见过 Pip。试着用英语问问她，文字和语音都可以。';actions=btn('询问管理员','ask-library','primary')+btn('◖)) 听一句示范','example-library');}else if(s.location==='art'){body='桌上有设备记录，美术社成员刚刚搬走了一件装饰物。';actions=btn(s.clues.includes('record')?'✓ 查看设备记录':'检查设备记录','record','primary')+btn('询问美术社成员','ask-art');}else if(s.location==='gym'){body='球场上没有机器人的踪迹。工作人员可以帮你确认。';actions=btn('和工作人员交谈','gym');}else{body=s.following?'Pip 已醒来，正在跟随你。回广场吧！':s.awake?'Pip 的蓝灯亮了！试着用英语让它跟你走。':s.clues.length<3?'这里有两台机器人。还需要更多线索，才能确定哪台是 Pip。':'两台白色机器人停在花盆旁。根据已知特征辨认 Pip。';actions=s.following?btn('返回广场','move','primary','data-value="plaza"'):s.awake?btn('对 Pip 说话','ask-follow','primary'):btn('蓝灯机器人','blue','primary')+btn('红灯机器人','red');if(chosen&&!s.awake)actions+=btn('按绿色按钮','green','orange')+btn('按红色按钮','wrong-button');}return `<section class="scene"><div class="scene-title"><h2>${p.icon} ${p.name}</h2><span class="muted">${p.en}</span></div><p>${body}</p><div class="actions">${actions}</div></section>`;}
function map(){const p=places[s.location];return `<section class="card"><div class="maphead"><strong>校园探索地图 <span class="muted">/ CAMPUS MAP</span></strong><span class="muted">点击地点前往 ↗</span></div><div class="map"><div class="path h"></div><div class="path v"></div><div class="pond"></div>${[[9,18],[23,22],[74,17],[88,23],[14,78],[27,83],[90,71],[65,91]].map(([x,y])=>`<span class="tree" style="left:${x}%;top:${y}%" aria-hidden="true">🌳</span>`).join('')}${Object.entries(places).map(([id,p])=>`<button class="place ${s.location===id?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-action="move" data-value="${id}" aria-label="前往${p.name}" ${s.location===id?'aria-current="location"':''}><span class="building" aria-hidden="true">${p.icon}</span><span class="label">${p.name}</span></button>`).join('')}<div class="actors" style="left:${p.x-4}%;top:${p.y+13}%"><span class="actor" title="你">🧑</span>${s.mode==='companion'?'<span class="actor coach" title="教练 Nova">👩</span>':''}${s.following?'<span class="actor" title="Pip">🤖</span>':''}</div><span class="mapcaption">N ↑ &nbsp; GREENFIELD CAMPUS · 自由探索</span></div>${scene()}</section><div class="bottomcards"><section class="card compact"><b>◎ 当前目标</b><p>${goal()}</p><div class="progress"><i style="width:${s.complete?100:s.following?85:s.awake?75:s.started?15+s.clues.length*15:0}%"></i></div><span class="muted">按自己的节奏来，不限时</span></section><section class="card compact"><b>▤ 我的线索本 <span class="muted">${s.clues.length} / 3</span></b><p>${s.clues.length?clues[s.clues.at(-1)][0]:'每一个发现，都离 Pip 更近一点。'}</p>${btn('打开线索本 ↗','notebook','chip')}</section></div>`;}
function notebook(){return `<section class="card notebook"><div class="eyebrow">FIELD NOTES</div><h2 style="margin-top:12px">我的线索本</h2><p class="muted">你亲自发现的信息，会保存在这里。</p>${s.clues.length?s.clues.map(c=>`<div class="clue"><small>0${s.clues.indexOf(c)+1} · ${clues[c][0]}</small><div>${clues[c][1]}</div><small>${clues[c][2]}</small><br><button class="chip" data-speak="${clues[c][1]}">◖)) 重听线索</button></div>`).join(''):'<div class="hero-icon">📓</div><p>还没有线索。去图书馆问问管理员吧。</p>'}${btn('返回地图','map','primary')}</section>`;}
function review(){if(!s.complete)return `<section class="card review"><h2>冒险还在继续</h2><p>${goal()}</p>${btn('继续探索','map','primary')}</section>`;return `<section class="card review"><div class="eyebrow">MISSION ACCOMPLISHED</div><div class="hero-icon">🤖 🌟</div><h2>Pip 回家了！</h2><p>你询问了目击者，连接起线索，亲手完成了任务。</p><div class="stats"><div><b>3 / 3</b><small>收集线索</small></div><div><b>${s.practice}</b><small>英语提交次数（含文字）</small></div></div><div class="clue">试着告诉 Nova：<br>“I found Pip in the greenhouse.”<br><small>也可以用自己的话，讲讲它为什么去了那里。</small></div><div class="exercise"><b>换个场景，还能听懂吗？</b><p>播放新的位置描述，再选择目的地。</p>${btn('◖)) 听新线索','transfer-audio')} ${btn('慢速重听','transfer-slow','chip')}<div class="actions" style="margin-top:14px">${btn('体育馆后面','transfer-right')}${btn('图书馆前面','transfer-wrong')}</div><p role="status">${transfer?'✓ 正确，你理解了新地点的位置关系。':''}</p></div><p class="muted">原型不评估发音或语言等级。这里展示的是实际任务与练习记录。</p>${btn('再玩一次','reset','primary')}</section>`;}
function coach(){return `<aside class="card coachpanel"><div class="coachhead"><div class="avatar">👩🏻‍🚀</div><div><strong>Nova <span class="muted">/ 你的教练</span></strong><div class="online">● 脚本教练 · 原型体验</div></div></div><div class="modes">${btn('♧ 同行陪伴','mode',s.mode==='companion'?'active':'','data-value="companion"')}${btn('◖)) 语音陪伴','mode',s.mode==='voice'?'active':'','data-value="voice"')}</div><div class="conversation"><div class="bubble" aria-live="polite">${esc(message)}${subtitles?`<div class="translation">${esc(translation)}</div>`:''}</div><div class="tools">${btn('◖)) 播放','listen')}${btn('慢速','slow')}${btn('停止','stop')}${btn(subtitles?'隐藏中文':'显示中文','subtitle')}</div><div class="tools">${btn('✦ 给我一点提示','hint')}${btn('怎么表达？','phrase-help')}</div></div><form class="composer" id="talk"><label for="utterance">用英语交流 · 支持文字或语音转写</label><input id="utterance" name="utterance" autocomplete="off" maxlength="300" placeholder="Have you seen a small robot?" aria-label="英语表达"><div class="actions"><button type="button" class="secondary" data-action="mic">${recording?'■ 停止录音':'♩ 语音输入'}</button><button type="submit" class="primary">发送 ↗</button></div><div class="status" id="voice-status" role="status">${recording?'正在聆听，再次点击可停止。':'语音转写可编辑，确认后再发送。'}</div></form></aside>`;}
function render(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">campus<span>quest.</span><small>英语同行冒险</small></div><nav class="nav" aria-label="主导航">${[['map','◈ 冒险地图'],['prep','▧ 语言背包'],['notebook','▤ 线索手记'],['review','☆ 冒险回顾']].map(([v,t])=>btn(t,v,view===v?'active':'')).join('')}</nav><div class="side-note">YOUR ADVENTURE<br><b>每一次开口，<br>都是新的发现。</b><br>你来探索，教练与你同行。</div></aside><main class="workspace"><div class="topbar"><span>探索营地 &nbsp; / &nbsp; 校园篇 &nbsp; / &nbsp; 第 01 关</span><span class="pill">🌱 A1–A2 · 入门探索员</span></div><header class="heading"><div><div class="eyebrow">THE MISSING ROBOT</div><h1>消失的科技节机器人</h1><p>跟随线索，找到 Pip。校园里的冒险，从你开口开始。</p></div><span class="pill">◷ 约 20 分钟 · 无倒计时</span></header>${!storage?'<div class="toast">浏览器存储不可用，本次进度仅保留到页面关闭。</div>':''}${notice?`<div class="toast" role="status">${esc(notice)}</div>`:''}<div class="layout"><div>${view==='prep'?prep():view==='notebook'?notebook():view==='review'?review():map()}</div>${coach()}</div><footer class="footnote"><span>EPISODE 01 · GREENFIELD CAMPUS</span><span>进度保存在此浏览器 · 脚本互动，不含真人联机 &nbsp; ${btn('重置进度','reset','chip')}</span></footer></main></div>`;}
function focusInput(){document.querySelector('#utterance')?.focus();}
function submit(text){if(!text.trim())return;commit('practice');const t=text.toLowerCase().replace(/[’']/g,'');if(!/[a-z]/i.test(t)){say('Try a short English sentence. You can use a phrase from your backpack.','试试一个简短的英文句子，也可以打开语言背包找提示。');return;}if(s.complete){say('Thanks for sharing your adventure! Try the new listening challenge, too.','谢谢你分享冒险经过！还可以试试新的听力挑战。');return;}if(/again|repeat|slower|slowly/.test(t)){say(message,translation);speak(message,true);return;}if(!s.started){say('Let’s collect our mission at the festival plaza first.','先去科技节广场领取任务吧。');return;}if(s.location==='library'&&/robot|pip/.test(t)&&/seen|see|where|find|went/.test(t)){commit('clue','witness');say(clues.witness[1],clues.witness[2]+' 已加入线索本。');return;}if(s.location==='art'&&/decoration|shiny|carried|take|took|where|robot|pip/.test(t)){commit('clue','decoration');say(clues.decoration[1],clues.decoration[2]+' 已加入线索本。');return;}if(s.location==='greenhouse'&&s.awake&&/follow|come with|lets go|let us go|back with/.test(t)){commit('follow');say('Beep! Pip is following you. Let’s head back to the plaza.','Pip 跟上你了！由你带它回科技节广场。');return;}if(/wake|button/.test(t)&&s.location==='greenhouse'&&s.clues.length===3){chosen=true;say('Press the green button, then wait for the blue light.','按绿色按钮，等待蓝灯亮起。请你亲手操作。');return;}say('I’m a scripted coach in this prototype. Try asking about Pip here, or ask me for a phrase.','原型支持有限场景表达。可以询问 Pip 的去向，或点“怎么表达？”获得当前场景示例。');}
function action(a,v){notice='';if(['map','prep','notebook','review'].includes(a)){view=a;render();return;}if(a==='move'){commit('move',v);chosen=false;hint=0;view='map';render();return;}if(a==='mode'){commit('mode',v);render();return;}if(a==='begin'||a==='skip'){commit('prepare');view='map';say('Let’s meet the festival organiser. You can collect the mission at the plaza.','准备好了！在广场领取任务，之后你决定去哪里。');return;}if(a==='start'){commit('start');say('Pip is a small white robot. It has a blue light. Where shall we start?','Pip 是白色小机器人，有一盏蓝灯。我们先去哪里？');return;}if(a==='brief'){say('Pip is a small white robot. It has a blue light.','Pip 是白色小机器人，有一盏蓝灯。');return;}if(a==='record'){commit('clue','record');say('The note says: blue light flashing. Pip flashes blue when it follows something bright.','设备记录已收集：蓝灯闪烁。Pip 追逐明亮的物品时会闪蓝灯。');return;}if(a==='ask-library'||a==='ask-art'||a==='ask-follow'){say(a==='ask-library'?'The librarian is listening. What would you like to ask?':a==='ask-art'?'The art club member is here. Ask where the decoration went.':'Pip is ready. Tell it to come with you.',a==='ask-library'?'管理员在听。试着问她是否见过机器人。':a==='ask-art'?'美术社成员就在这里，问问装饰物去了哪里。':'Pip 准备好了，用英语邀请它跟你走。');focusInput();return;}if(a==='example-library'){speak('Have you seen a small robot?');return;}if(a==='gym'){say('I haven’t seen a robot here. Try asking at the library.','工作人员说这里没见过机器人，可以去图书馆问问。');return;}if(a==='blue'){if(s.clues.length<3){say('We need more evidence. Let’s check our notes before choosing.','还需要收集三条线索，才能确认目标。');return;}chosen=true;say('That’s Pip! Press the green button, then wait for the blue light.','找到 Pip 了！按绿色按钮，等待蓝灯亮起。');return;}if(a==='red'||a==='wrong-button'){say('Take another look. What colour did the instructions mention?','再想一想，描述或说明里提到的是哪种颜色？可以重听。');return;}if(a==='green'&&chosen){commit('wake');say('Pip is awake! Can you ask it to follow you?','Pip 醒了！试着说 Follow me, Pip，或用自己的话邀请它同行。');return;}if(a==='finish'){commit('finish');if(s.complete){view='review';say('You did it! Where did you find Pip?','你完成了任务！试着用英语讲讲在哪里找到了 Pip。');}return;}if(a==='voice-preview'){speak('Hello! The robot is behind the library.');return;}if(a==='quiz-audio'||a==='quiz-slow'){speak('The robot is behind the library.',a==='quiz-slow');return;}if(a==='quiz-right'){quiz=true;notice='听辨正确！也可以在右侧试着说一句 Have you seen a small robot?';render();return;}if(a==='quiz-wrong'){notice='再听一次，注意 behind。可以反复尝试。';render();return;}if(a==='transfer-audio'||a==='transfer-slow'){speak('The robot is behind the gym.',a==='transfer-slow');return;}if(a==='transfer-right'){transfer=true;notice='正确！这次地点换成了体育馆。';render();return;}if(a==='transfer-wrong'){notice='再听一次，注意 gym 和 behind。';render();return;}if(a==='listen'||a==='slow'){speak(message,a==='slow');return;}if(a==='stop'){stopSpeech();return;}if(a==='subtitle'){subtitles=!subtitles;render();return;}if(a==='phrase-help'){say(s.location==='art'?'Where did you take the decoration?':s.location==='greenhouse'?'Follow me, Pip.':s.complete?'I found Pip in the greenhouse.':'Have you seen a small robot?','可以参考这句表达，也可以换成自己的说法。');return;}if(a==='hint'){const h=!s.started?['Where does our mission start?','Look for the festival organiser.','Go to the plaza and collect the mission.']:s.clues.length<3?['What evidence do we have so far?','A witness and the art room may help.','Ask the librarian about Pip. Check the art room note and ask about the decoration.']:!s.awake?['What does Pip look like?','Remember the blue light.','Visit the greenhouse, select the blue-light robot, and press the green button.']:!s.following?['Pip is ready to move.','How can you invite it along?','Try saying: Follow me, Pip.']:['Where did we start?','The festival needs Pip back.','Return to the plaza and hand in the mission.'];say(h[Math.min(hint++,2)],`提示 ${Math.min(hint,3)}/3 · ${goal()}。由你决定并完成操作。`);return;}if(a==='mic'){mic();return;}if(a==='reset'){const d=document.createElement('dialog');d.innerHTML='<h2>重新开始冒险？</h2><p>这会清除本浏览器里的当前关卡进度。</p><div class="actions"><button class="secondary" id="cancel-reset">继续冒险</button><button class="primary" id="confirm-reset">确认重置</button></div>';document.body.append(d);d.showModal();d.querySelector('#cancel-reset').onclick=()=>d.remove();d.querySelector('#confirm-reset').onclick=()=>{recording?.abort();recording=null;stopSpeech();s=initial();try{localStorage.removeItem(KEY);}catch{}view='prep';quiz=false;transfer=false;chosen=false;hint=0;d.remove();say('A fresh adventure! Let’s prepare your language backpack.','新的冒险开始了，先准备语言背包吧。');};return;}}
function mic(){if(recording){recording.stop();return;}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){notice='此浏览器暂不支持语音识别。请用文字输入，或在支持语音识别的浏览器中打开。';render();return;}const d=document.createElement('dialog');d.innerHTML='<h2>开始语音输入</h2><p>浏览器可能将音频发送到其语音服务进行转写。本应用不保存录音；你可以编辑文字后再发送。</p><div class="actions"><button class="secondary" id="no-mic">使用文字</button><button class="primary" id="yes-mic">开启麦克风</button></div>';document.body.append(d);d.showModal();d.querySelector('#no-mic').onclick=()=>{d.remove();focusInput();};d.querySelector('#yes-mic').onclick=()=>{d.remove();stopSpeech();const r=new R();recording=r;r.lang='en-US';r.interimResults=false;r.onresult=e=>{const input=document.querySelector('#utterance');if(input)input.value=e.results[0][0].transcript;};r.onerror=e=>{document.querySelector('#voice-status').textContent=e.error==='not-allowed'?'麦克风权限未开启，请使用文字输入。':'未能识别，请重试或输入文字。';};r.onend=()=>{recording=null;const b=document.querySelector('[data-action="mic"]');if(b)b.textContent='♩ 语音输入';};render();try{r.start();}catch{recording=null;notice='无法开始录音，请使用文字输入。';render();}};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.speak){speak(b.dataset.speak);return;}if(b.dataset.action)action(b.dataset.action,b.dataset.value);});document.addEventListener('submit',e=>{if(e.target.id!=='talk')return;e.preventDefault();submit(new FormData(e.target).get('utterance')||'');});render();

document.addEventListener('change',e=>{if(e.target.id==='voice-choice'){stopSpeech();preferredVoice=e.target.value;try{localStorage.setItem('campus-voice',preferredVoice);}catch{}}});
window.speechSynthesis?.addEventListener('voiceschanged',()=>{const select=document.querySelector('#voice-choice');if(select)select.innerHTML=voiceOptions();});
